mapper.select:
SELECT t.opportunity_id, t.tenant_id, t.customer_id, t.customer_name, t.opportunity_name, t.stage, t.source, t.expected_amount, t.win_rate, t.expected_sign_date, t.owner_id, t.owner_name, t.dept_id, t.dept_name, t.contact_id, t.contact_name, t.latest_follow_up_time, t.stage_changed_time, t.lost_reason, t.remark, t.status, t.deleted, t.create_by, t.create_time, t.update_by, t.update_time, c.dept_id AS scope_dept_id, c.owner_id AS scope_owner_id FROM crm_opportunity t INNER JOIN crm_customer c ON c.customer_id = t.customer_id AND c.deleted = '0' WHERE t.deleted = '0'
AND t.customer_id = #{query.customerId}
AND t.opportunity_name LIKE CONCAT('%', #{query.opportunityName}, '%')
AND t.stage = #{query.stage}
AND t.owner_id = #{query.ownerId}
ORDER BY t.update_time DESC
